import { relative, resolve, sep } from 'node:path'
import { fileURLToPath } from 'node:url'

/**
 * Resolves a diagnostic filename relative to its workspace.
 * @param root - The workspace root.
 * @param filename - The native filename or file URL.
 * @returns The relative filename with forward slashes.
 */
export function resolveDiagnosticFilename(root: string, filename: string): string {
	const path = filename.startsWith('file:') ? fileURLToPath(filename) : filename
	return relative(resolve(root), resolve(root, path)).split(sep).join('/')
}

