import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { pathToFileURL } from 'node:url'
import { expect, it } from 'vitest'
import { resolveDiagnosticFilename } from '../../../../src/server/diagnostics/helpers.js'

it('decodes a file URL relative to the workspace without changing escaped filename characters', () => {
	const root = join(tmpdir(), 'diagnostic root % Ω')
	const filename = join(root, 'src', 'member # %.ts')
	expect(resolveDiagnosticFilename(root, pathToFileURL(filename).href)).toBe('src/member # %.ts')
	expect(resolveDiagnosticFilename(root, filename)).toBe('src/member # %.ts')
	expect(resolveDiagnosticFilename(root, join('src', 'member # %.ts'))).toBe('src/member # %.ts')
})

